# R/assets.R

library(shiny)
library(bslib)

theme_odc_safe <- bs_theme(
  version   = 5,
  bg        = "#f0f2f5",
  fg        = "#1f2937",
  primary   = "#427c98",
  success   = "#72c02c",
  secondary = "#1C2D5C",
  base_font = font_collection(
    "-apple-system", "BlinkMacSystemFont", "Segoe UI", "Roboto",
    "Helvetica Neue", "Arial", "sans-serif"
  )
)

# Centralized chart color palette
ODC_CHART_COLORS <- c(
  "#1C2D5C", "#2a4382", "#427c98", "#619bb8", "#72c02c",
  "#94d952", "#f59e0b", "#8b5cf6", "#ec4899", "#64748b"
)

# Logo embedded as base64 data URI
LOGO_SRC <- "data:image/png;base64,"

# Local assets
odc_local_assets <- tagList(
  tags$link(rel = "stylesheet", href = "css/odc-main.css"),
  tags$script(src = "js/odc-main.js"),
  tags$script(src = "js/odc-shiny-head.js")
)
